309	/// Compute the combat damage multiplier from DoubleCombatDamage effects (e.g., Inquisitor's Flail).
310	/// Each source doubles independently: 1 Flail = x2, 2 Flails = x4, 3 = x8, etc.
311	fn combat_damage_multiplier(state: &GameState, creature_id: ObjectId, registry: &CardRegistry) -> u32 {
312	    let count = state.count_continuous_effect(creature_id, &|e| {
313	        match e {
314	            crate::types::ContinuousEffect::DoubleCombatDamage { scope } => Some(scope),
315	            _ => None,
316	        }
317	    }, registry);
318	    1u32 << count // 2^count
319	}
