39	    fn target_requirement(&self) -> TargetRequirement {
40	        TargetRequirement::PlayerOnly
41	    }
42	
43	    fn on_resolve(&self, state: &mut GameState, object_id: ObjectId, targets: &[Target], _registry: &CardRegistry) {
44	        crate::cards::helpers::resolve_curse(state, object_id, targets);
45	    }
46	
47	    fn on_upkeep(&self, state: &mut GameState, self_id: ObjectId, _registry: &CardRegistry) {
48	        let cursed_player = match state.get_object(self_id) {
49	            Some(o) if o.zone == Zone::Battlefield => o.attached_to_player,
50	            _ => return,
51	        };
52	        let cursed_player = match cursed_player {
53	            Some(p) => p,
54	            None => return,
